add_action('wp_footer', function(){
  if (is_admin()) return;
  ?>
  <script id="zp-suite-polish-166-js">
  (function(){
    function boot(){
      document.querySelectorAll('.zpStickyEstimate__btn:not([data-zp-icon-fixed])').forEach(function(b){
        b.setAttribute('data-zp-icon-fixed','1');
        if(!b.querySelector('svg,[data-lucide]')) b.insertAdjacentHTML('afterbegin','<i data-lucide="sparkles"></i>');
      });
      document.querySelectorAll('.zpStickyEstimate__mail:not([data-zp-icon-fixed])').forEach(function(b){
        b.setAttribute('data-zp-icon-fixed','1');
        if(!b.querySelector('svg,[data-lucide]')) b.insertAdjacentHTML('afterbegin','<i data-lucide="mail"></i>');
      });
      if(window.lucide && typeof window.lucide.createIcons==='function'){
        try{window.lucide.createIcons({attrs:{'stroke-width':1.9,'stroke-linecap':'round','stroke-linejoin':'round'}})}catch(e){}
      }
    }
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true}); else boot();
    window.addEventListener('load',boot,{once:true,passive:true});
  })();
  </script>
  <?php
}, 999999);
